const float[4] ARM_COEFFICIENTS = float[4](
    1.3448505,
    -0.2382864,
    0.0481382,
    0.00000001498054
);

const int ARM_ITERATION_COUNT = 10;

const float LOBE_RADIUS = 0.3161;
const vec2 LOBE_CENTER = vec2(1. - LOBE_RADIUS, 0.);

vec2 rotateRad(vec2 v, float angleRad) {
    float cosAngle = cos(angleRad);
    float sinAngle = sin(angleRad);

    return vec2(
        v.x * cosAngle - v.y * sinAngle,
        v.x * sinAngle + v.y * cosAngle
    );
}

vec2 rotateDeg(vec2 v, float angleDeg) {
    return rotateRad(v, radians(angleDeg));
}

vec2 lineIntersection(vec2 a1, vec2 a2, vec2 b1, vec2 b2) {
    vec2 d1 = a2 - a1;
    vec2 d2 = b2 - b1;

    float t = (d1.x * (b1.y - a1.y) - d1.y * (b1.x - a1.x)) / (d1.y * d2.x - d1.x * d2.y);

    return b1 + t * d2;
}

vec2 flowerTransform(vec2 pos) {
    float angleRad = atan(pos.y, pos.x);
    float newAngleRad = mod(angleRad, radians(60.)) + radians(60.);
    float angleDiffRad = newAngleRad - angleRad;

    pos = rotateRad(pos, angleDiffRad);
    pos.x = abs(pos.x);

    return pos.yx;
}

float arm(float x) {
    return ARM_COEFFICIENTS[0] * pow(x, 2.)
        + ARM_COEFFICIENTS[1] * x
        + ARM_COEFFICIENTS[2]
        + ARM_COEFFICIENTS[3] * pow(x, -7.);
}

float armSlope(float x) {
    return 2. * ARM_COEFFICIENTS[0] * x
        + ARM_COEFFICIENTS[1]
        - 7. * ARM_COEFFICIENTS[3] * pow(x, -8.);
}

float armSDF(vec2 pos) {
    float x = float(pos.x >= 0.164) * pos.x;

    x += float(pos.x < 0.164) * lineIntersection(pos, vec2(0.164, 0.164 / sqrt(3.)), vec2(.124, .072), vec2(.164, .05)).x;

    for (int i = 0;  i < ARM_ITERATION_COUNT;  i++) {
        float y = arm(x);
        float m = armSlope(x);
        float b = y - m*x;

        x = max((pos.x - m*(b - pos.y)) / (m*m + 1.), 0.124);
    }

    float y = arm(x);

    return length(pos - vec2(x, y)) * (float(pos.y > y) * 2. - 1.);
}

float lobeSDF(vec2 pos) {
    return length(pos - LOBE_CENTER) - LOBE_RADIUS;
}

float flowerSDF(vec2 pos) {
    pos = flowerTransform(pos);

    vec2 offset = pos - LOBE_CENTER;
    float angleDeg = degrees(atan(offset.y, offset.x));

    return float(angleDeg <= 135.) * lobeSDF(pos) + float(angleDeg > 135.) * armSDF(pos);
}

float randFloat(vec2 seed) {
    return fract(
        sin(
            dot(seed + 1., vec2(12.9898,78.233))
        ) * 43758.5453123
    );
}

vec3 randColor(vec2 seed) {
    return vec3(randFloat(seed), randFloat(seed + .1), randFloat(seed + .2));
}

vec4 flowerPlane(vec2 pos, float seed) {
    vec2 gridCell = floor((pos + 1.) / 2.);
    vec2 gridSeed = gridCell + seed;
    float gridFloat = randFloat(gridSeed);

    // tile endlessly
    pos = (mod(pos + 1., 2.) - 1.) * 1.;

    const float maxSpinSpeedDeg = 45.;

    float spinSpeedDeg = mix(-maxSpinSpeedDeg, maxSpinSpeedDeg, gridFloat);

    float angleDeg = spinSpeedDeg * iTime;
    pos = rotateDeg(pos, angleDeg);

    const float minScale = .6;
    const float maxScale = .95;

    float scale = mix(minScale, maxScale, gridFloat);

    float flowerSD = flowerSDF(pos / scale);

    float blur = .01;
    float mask = smoothstep(blur, -blur, flowerSD);

    return vec4(mask * randColor(gridSeed), mask);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 pos = (2. * fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);

    vec4 background = vec4(vec3(1., .5, .8), 1.);

    vec4 col = background;

    float seed = 3.4;

    const float maxDistance = 12.;
    const float fogDensity = .2;
    const float[3] distances = float[3](10., 5., 3.);
    const vec2[3] offsets = vec2[3](
        vec2(.32, .7),
        vec2(.15, -.2),
        vec2(0., 0.)
    );

    const vec2 velocity = vec2(.2, -1.);

    for (int i = 0;  i < 3;  i++) {
        float distance = distances[i];
        float fog = (1. - 1. / exp(pow(fogDensity * distance, 2.))) * distance / maxDistance;
        float scale = atan(1.) / atan(1./distance);

        vec2 flowerPos = pos;
        flowerPos *= scale;
        flowerPos -= offsets[i] + velocity * iTime;


        vec4 flowers = flowerPlane(flowerPos, seed);
        flowers = vec4(mix(flowers.rgb, background.rgb, fog), flowers.a);

        col = mix(col, flowers, flowers.a);

        seed *= 2.;
    }


    fragColor = col;
}
